<template>
  <div class="material-detail-page">
    <nav class="crumb"><router-link to="/learning">学习中心</router-link><span>/</span><router-link :to="{name:'market-learning-materials'}">付费学习资料</router-link><span>/</span><b>{{ item?.material?.courseCode||"内容详情" }}</b></nav>
    <template v-if="item">
      <el-alert v-if="!item.material?.metadataComplete" type="warning" :closable="false" show-icon title="这是升级前发布的资料，课程代码、适用学期或资料类型尚未补充。发布者再次编辑时必须完善。" />
      <section class="detail-shell cpu-card">
        <div class="gallery">
          <div class="main-image"><img v-if="activeImage" :src="activeImage" :alt="item.title" /><div v-else class="fallback"><img src="/brand/kaopu-cloud.svg" alt="" /><b>KAOPU LEARNING</b></div></div>
          <div v-if="item.images.length>1" class="thumbs"><button v-for="image in item.images" :key="image.id" :class="{active:activeImage===image.url}" @click="activeImage=image.url"><img :src="image.url" alt="预览" /></button></div>
        </div>
        <div class="summary">
          <div class="summary-tags"><span>{{ item.material?.courseCode||"课程代码待补充" }}</span><span>{{ typeLabel }}</span><span>{{ semesterLabel }}</span></div>
          <h1>{{ item.title }}</h1><p class="description-brief">{{ item.description }}</p>
          <div class="price"><small>¥</small><strong>{{ item.price }}</strong><del v-if="item.originalPrice">¥{{ item.originalPrice }}</del></div>
          <dl><div><dt>资料版本</dt><dd>{{ item.material?.versionLabel||item.material?.activeVersion?.label||"未标注" }}</dd></div><div><dt>文件格式</dt><dd>{{ item.material?.fileFormats?.join(" / ")||actualFormats||"未标注" }}</dd></div><div><dt>资料页数</dt><dd>{{ item.material?.pageCount ? `${item.material.pageCount} 页` : "未标注" }}</dd></div><div><dt>已收藏</dt><dd>{{ item.favoriteCount }}</dd></div></dl>
          <div v-if="!item.mine" class="buy-actions"><el-button :icon="item.favorited?StarFilled:Star" @click="favorite">{{ item.favorited?"已收藏":"收藏" }}</el-button><el-button type="primary" size="large" :loading="submitting" :disabled="item.status!=='active'||item.seller.publisherActive===false" @click="buy">{{ item.seller.publisherActive === false ? "发布者暂停销售" : "立即购买" }}</el-button></div>
          <div v-else class="buy-actions"><el-button type="primary" @click="router.push({name:'market-learning-materials-edit',params:{id:item.id}})">编辑内容</el-button><el-button @click="router.push({name:'market-learning-material-library'})">我的资料库</el-button></div>
          <p v-if="!auth.isLoggedIn" class="login-tip">登录并完成 XJTLU 认证后可以购买、收藏和下载资料。</p>
          <div class="protection"><b>付款与交付说明</b><span>资料款由你直接支付给资料发布者，平台不代收。上传付款凭证后，发布者确认到账，系统才会自动解锁完整文件。</span></div>
        </div>
      </section>

      <section class="content-grid">
        <article class="cpu-card content-card"><h2>资料介绍</h2><p>{{ item.description }}</p><div class="public-actions"><el-button plain @click="router.push({path:'/post',query:{board:'study',itemId:item.id}})">发起关联讨论</el-button><el-button plain @click="share">分享资料</el-button><el-button v-if="auth.isLoggedIn&&!item.mine" text type="danger" @click="reportOpen=true">举报资料</el-button></div></article>
        <aside class="cpu-card creator-card"><div><UserAvatar :size="52" :src="item.seller.avatar" :name="item.seller.nickname" /><span><strong>{{ item.seller.nickname||item.seller.username }}</strong><small>{{ publisherLevelLabel }} · 质量分 {{ item.seller.creatorQualityScore ?? 60 }}</small></span></div><dl><div><b>{{ item.seller.creatorAverageRating || "—" }}</b><span>成交评分（{{ item.seller.creatorRatingCount || 0 }}）</span></div><div><b>{{ item.seller.creatorCompletedOrderCount || 0 }}</b><span>完成订单</span></div></dl><p>退款率 {{ item.seller.creatorRefundRate || 0 }}% · 争议率 {{ item.seller.creatorDisputeRate || 0 }}%。付款、交付、访问和售后均保留记录。</p></aside>
      </section>

      <section class="metadata cpu-card"><header><span>STRUCTURED INFORMATION</span><h2>资料信息</h2></header><div class="metadata-grid"><div><span>课程代码</span><b>{{ item.material?.courseCode||"待补充" }}</b></div><div><span>适用学期</span><b>{{ semesterLabel }}</b></div><div><span>资料类型</span><b>{{ typeLabel }}</b></div><div><span>学院</span><b>{{ item.material?.college||"未标注" }}</b></div><div><span>专业</span><b>{{ item.material?.major||"未标注" }}</b></div><div><span>语言</span><b>{{ optionLabel(meta.languages,item.material?.language)||"未标注" }}</b></div><div><span>文件格式</span><b>{{ item.material?.fileFormats?.join(" / ")||actualFormats||"未标注" }}</b></div><div><span>页数</span><b>{{ item.material?.pageCount ? `${item.material.pageCount} 页` : "未标注" }}</b></div><div><span>原创声明</span><b>{{ optionLabel(meta.originalityOptions,item.material?.originalityKind)||"未声明" }}</b></div></div><p v-if="item.material?.originalityStatement" class="statement">{{ item.material.originalityStatement }}</p></section>

      <section v-if="item.material?.activeVersion?.files?.length" class="file-manifest cpu-card"><header><span>FILE MANIFEST</span><h2>真实试读与文件清单</h2><p>试读页从实际交付 PDF 中抽取并带有样张水印；付款确认后完整文件会写入买家追踪水印。</p></header><div><article v-for="file in item.material.activeVersion.files" :key="file.id"><span>{{ file.format }}</span><div><b>{{ file.originalName }}</b><small>{{ formatBytes(file.fileSize) }}<template v-if="file.pageCount"> · {{ file.pageCount }}页</template><template v-if="file.previewEnabled"> · 试读 {{ file.previewPageStart }}-{{ file.previewPageEnd }} 页</template></small></div><el-button v-if="file.previewEnabled" size="small" type="primary" plain @click="openSample(file.id)">真实试读</el-button></article></div></section>

      <section class="ratings cpu-card"><header><span>VERIFIED PURCHASE REVIEWS</span><h2>已购评价</h2><p>仅完成订单的实际买家可以评价，退款订单评价自动退出质量分计算。</p></header><div class="rating-summary"><strong>{{ ratings.summary.overall || "—" }}</strong><span>{{ ratings.summary.count }} 条已购评价</span><small>准确 {{ ratings.summary.accuracy || "—" }} · 实用 {{ ratings.summary.usefulness || "—" }} · 描述相符 {{ ratings.summary.descriptionMatch || "—" }} · 文件质量 {{ ratings.summary.fileQuality || "—" }}</small></div><div v-if="ratings.list.length" class="rating-list"><article v-for="rating in ratings.list" :key="rating.id"><div><UserAvatar :size="30" :src="rating.buyer?.avatar" :name="rating.buyer?.nickname" /><b>{{ rating.buyer?.nickname || rating.buyer?.username || "已购用户" }}</b><el-rate :model-value="rating.overall" disabled /></div><p>{{ rating.content || "买家未填写文字评价" }}</p><small>{{ new Date(rating.createdAt).toLocaleDateString("zh-CN") }}</small></article></div><el-empty v-else description="暂无已购评价" :image-size="70" /></section>

