<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from "vue";import { useRoute,useRouter } from "vue-router";import { Star,StarFilled } from "@element-plus/icons-vue";import { ElMessage } from "element-plus";import { learningMaterialsApi,type LearningMaterialItem,type LearningMaterialMeta,type LearningMaterialRatingResult } from "@/api/learningMaterials";import { marketApi } from "@/api/market";import { useAuthStore } from "@/stores/auth";import UserAvatar from "@/components/common/UserAvatar.vue";import MarketShareDialog from "@/components/market/MarketShareDialog.vue";
const route=useRoute(),router=useRouter(),auth=useAuthStore();const item=ref<LearningMaterialItem|null>(null),related=ref<LearningMaterialItem[]>([]),loading=ref(false),submitting=ref(false),activeImage=ref(""),reportOpen=ref(false),shareOpen=ref(route.query.published==="1");const report=reactive({reason:"",detail:""});const reportReasons=["疑似侵权或盗版","作业答案或代写内容","泄露试题","资料描述不实","恶意引流","文件存在安全风险","其他"];
const meta=reactive<LearningMaterialMeta>({category:{id:0,slug:"digital_goods",name:"电子资料",icon:"📁",description:"",fulfillmentType:"digital",imageRequired:false,enabled:true,sort:30,itemCount:0},semesters:[],formats:[],languages:[],originalityOptions:[],supportCategories:[],types:[],legacyIncompleteCount:0});const ratings=reactive<LearningMaterialRatingResult>({summary:{count:0,overall:0,accuracy:0,usefulness:0,descriptionMatch:0,fileQuality:0},list:[]});const typeLabel=computed(()=>item.value?.material?.type?.name||"资料类型待补充");const semesterLabel=computed(()=>optionLabel(meta.semesters,item.value?.material?.applicableSemester)||"学期待补充");const actualFormats=computed(()=>Array.from(new Set(item.value?.material?.activeVersion?.files?.map(row=>row.format)||[])).join(" / "));const publisherLevelLabel=computed(()=>({excellent:"卓越发布者",reliable:"可信发布者",certified:"资料发布者"}[item.value?.seller.creatorLevel||"certified"]));
onMounted(load);watch(()=>route.params.id,load);async function load(){const id=Number(route.params.id);if(!id)return;loading.value=true;try{const emptyRatings:LearningMaterialRatingResult={summary:{count:0,overall:0,accuracy:0,usefulness:0,descriptionMatch:0,fileQuality:0},list:[]};const [nextItem,nextMeta,nextRatings]=await Promise.all([learningMaterialsApi.item(id,{suppressErrorMessage:true}),learningMaterialsApi.meta({suppressErrorMessage:true}),learningMaterialsApi.ratings(id,{suppressErrorMessage:true}).catch(()=>emptyRatings)]);item.value=nextItem;Object.assign(meta,nextMeta);Object.assign(ratings,nextRatings);activeImage.value=nextItem.cover;try{const result=await learningMaterialsApi.items({courseCode:nextItem.material?.courseCode||undefined,semester:nextItem.material?.applicableSemester||undefined,size:5},{suppressErrorMessage:true});related.value=result.list.filter(row=>row.id!==id).slice(0,4)}catch{related.value=[]}}catch{item.value=null;related.value=[]}finally{loading.value=false}}
function optionLabel(options:Array<{value:string;label:string}>,value?:string){return options.find(row=>row.value===value)?.label||""}function formatBytes(value:number){if(value<1024*1024)return `${Math.max(1,Math.round(value/1024))} KB`;return `${(value/1024/1024).toFixed(1)} MB`}
function requireLogin(){if(auth.isLoggedIn)return true;router.push({name:"login",query:{redirect:route.fullPath}});return false}async function favorite(){if(!item.value||!requireLogin())return;const result=await marketApi.favorite(item.value.id);item.value.favorited=result.favorited;item.value.favoriteCount=result.favoriteCount}
async function buy(){if(!item.value||!requireLogin())return;submitting.value=true;try{const order=await learningMaterialsApi.createOrder(item.value.id);ElMessage.success("订单已创建，请向资料发布者付款并上传凭证");router.push({name:"market-learning-order-detail",params:{id:order.id},query:{side:"buyer"}})}finally{submitting.value=false}}
async function submitReport(){if(!item.value||!report.reason)return ElMessage.warning("请选择举报原因");submitting.value=true;try{await marketApi.report(item.value.id,report);reportOpen.value=false;ElMessage.success("举报已提交，平台将核查资料和版本记录")}finally{submitting.value=false}}function share(){shareOpen.value=true}
function openSample(fileId:number){if(!item.value)return;window.open(learningMaterialsApi.sampleUrl(item.value.id,fileId),"_blank","noopener,noreferrer")}
</script>

